// Repro for bucket B1 (data_byte): data bits must be sent least significant first.
// Check label: data_byte_lsb_first
module tb_repro_data_byte;
    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer passed = 0;
    integer failed = 0;
    integer k;
    integer guard;
    reg [7:0] rx;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(4)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task send_and_check(input [7:0] d);
        begin
            @(negedge clk); data = d; start = 1'b1;
            @(negedge clk); start = 1'b0;          // negedge 1 of the start bit
            repeat (2) @(negedge clk);             // negedge 3: middle of the start bit
            for (k = 0; k < 8; k = k + 1) begin
                repeat (4) @(negedge clk);         // negedge 4k+7: middle of data bit k
                rx[k] = tx;
            end
            if (rx === d) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("CHECK data_byte_lsb_first FAILED: sent %h received %h", d, rx);
            end
            guard = 0;
            while (busy && guard < 1000) begin
                @(negedge clk);
                guard = guard + 1;
            end
            repeat (2) @(negedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        send_and_check(8'h01);
        send_and_check(8'h80);
        send_and_check(8'h4B);
        send_and_check(8'hF0);
        send_and_check(8'h37);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
