// Repro for bucket B3 (frame_period): a frame (start, 8 data, parity, stop) keeps
// busy high for exactly 11 * CLKS_PER_BIT clock cycles.
// Check label: frame_busy_cycles
module tb_repro_frame_period;
    localparam integer CPB = 4;
    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer passed = 0;
    integer failed = 0;
    integer cycles;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task send_and_check(input [7:0] d);
        begin
            @(negedge clk); data = d; start = 1'b1;
            @(negedge clk); start = 1'b0;
            cycles = 0;
            while (busy && cycles < 1000) begin
                cycles = cycles + 1;
                @(negedge clk);
            end
            if (cycles == 11 * CPB) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("CHECK frame_busy_cycles FAILED: data %h busy for %0d cycles, expected %0d",
                         d, cycles, 11 * CPB);
            end
            repeat (2) @(negedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        send_and_check(8'h55);
        send_and_check(8'h00);
        send_and_check(8'hC3);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
